INSERT INTO feature VALUES('nix-type-provider','metaprograms','The Nix type provider','tactics-over-goals','planned','notable',NULL,'A splice reads a Nix derivation, as `nix derivation show` prints it, or a `nixpkgs` attribute, as `nix eval --json` prints its `meta` and `outputs`, into a record type the checker admits and a value of it; today the records stand written by hand for `hello`, each beside the JSON its read printed.',NULL,'corpus/model/package/nix-derivation.gandr corpus/model/package/nix-attribute.gandr',NULL,'#2991');
